def facts():
    out = {}
    for name, t in (("batched", T(BX) @ T(BY)), ("shared", T(BX) @ T(W2))):
        (p,) = [L.plan(a) for a in asts(t)]
        out[name] = {
            "kind": p.kind,
            "batch": [U.extent(r) for r in p.batch],
            "b_reads_batch": p.kind == "matmul" and any(p.b.c(r) for r in p.batch),
        }
    return out
